select public.prepify_load_bank('Chemistry', 2, $j$[["Which state of matter is most likely to be found in stars due to extremely high temperatures?",["Solid","Plasma","Liquid","Bose-Einstein Condensate"],"B",3,0,"2a05a3c160d7",1],["Which state of matter would have the highest fluidity?",["Plasma","Gas","Solid","Liquid"],"B",3,0,"b1c8cf9a2c30",1],["Which of these is a pure substance composed of only one type of atom?",["Water","Air","Gold","Brass"],"C",3,0,"92d5f75c05c1",1],["In which of the following is the arrangement of particles the least ordered?",["Diamond","Liquid water","Oxygen gas","Graphite"],"C",3,0,"345d99898525",1],["Which mixture type shows the Tyndall effect, but its particles do not settle when kept stationary?",["Solution","Suspension","Colloid","Element"],"C",3,0,"409aa573d2ef",1],["The conversion of liquid water into steam is an example of:",["Physical change","Decomposition","Nuclear change","Chemical change"],"A",3,0,"1bdf12c72f9b",1],["Which sample is most likely to have the highest density under normal conditions?",["Oxygen gas","Water vapor","Ice cube","Iron nail"],"D",3,0,"b9d82fcce497",1],["If you mix sugar in water and it disappears, the resulting mixture is best described as:",["A heterogeneous suspension","A homogeneous solution","A colloid","A pure compound"],"B",3,0,"208af0d9219b",1],["What is the key difference between a colloid and a suspension?",["Colloids are homogeneous; suspensions are heterogeneous","Colloid particles are smaller and do not settle, unlike suspension particles","Suspensions are smaller than colloids","There is no difference"],"B",3,0,"4562a0a54ac3",1],["Why are diamond and graphite considered allotropes of carbon?",["They contain different elements.","They have different atomic numbers.","They are different structural forms of the same element.","They have different chemical compositions."],"C",3,0,"dad87ab81f53",1],["The ability of a liquid to flow is directly related to its:",["Compressibility","Fluidity","Density","Hardness"],"B",3,0,"52bd2157c36e",1],["Which change is most likely to increase the solubility of many solid solutes in water?",["Lowering temperature","Stirring only","Removing solvent","Increasing temperature"],"D",3,0,"4f6fa5284e89",1],["The dissolved and undissolved solute in a saturated solution are in:",["Chemical reaction","Nuclear equilibrium","Dynamic equilibrium","Thermal decomposition"],"C",3,0,"63d4dfe0f0a3",1],["Which substance can be separated into its components by physical means?",["Pure Gold","Sucrose","Carbon Dioxide","A mixture of salt and sand"],"D",3,0,"1af984e5438b",1],["What is the result when a saturated solution is cooled down?",["It becomes unsaturated","It may form crystals as the solubility decreases","It turns into a gas","The mass of the solvent increases"],"B",3,0,"226c4e248113",1],["Why does gas exert pressure on the walls of its container?",["Because of the continuous random motion and collisions of particles","Because the particles are stationary","Because the container is heated","Because gas particles attract each other strongly"],"A",3,0,"09a7088b46db",1],["What is most likely observed when extra solute is added to a saturated solution?",["Solvent disappears","The solution becomes a gas","Solute remains undissolved","All solute dissolves instantly"],"C",3,0,"67034f6ba926",1],["Which factor has the greatest effect on whether a solution becomes saturated?",["Amount of solute and temperature","Color of solvent","Shape of container","Density of air"],"A",3,0,"b32255e779ef",1],["In soft drinks, the substance present in the greatest amount is generally:",["Sugar","Carbon dioxide","Water","Salt"],"C",3,0,"8fca0ed94970",1],["Compared with diamond, graphite:",["Has no carbon atoms","Is harder","Has a higher melting point","Conducts electricity better"],"D",3,0,"d1356997af2c",1],["Which property makes diamond suitable for use as a cutting tool?",["Electrical conductivity","Soft structure","Solubility in water","Extreme hardness"],"D",3,0,"95adaeb21d35",1],["An example of a liquid-in-gas colloid is:",["Fog","Smoke","Jelly","Milk"],"A",3,0,"a3bbbf6e9101",1],["A scientist wants to separate mud from water. This is an example of separating a:",["True solution","Suspension","Colloid","Compound"],"B",3,1,"934630e027ce",1],["Why is a suspension considered a heterogeneous mixture?",["Because its components are chemically bonded","Because its components are not uniformly distributed and can be separated","Because it is invisible to the naked eye","Because it is a pure substance"],"B",3,0,"7565e80de703",1],["Which property of liquids allows them to take the shape of their container?",["High density","Fluidity","Compressibility","Rigid structure"],"B",3,0,"ab5ff84f326b",1],["A liquid changes into a gas when:",["Particle motion decreases","Chemical bonds are permanently broken","New substances are formed","Particles gain sufficient energy to escape"],"D",3,0,"fb762c1f7bfa",1],["If the intermolecular forces in a substance are significantly weakened without changing the chemical composition, which phase transition is most likely occurring at a macroscopic level?",["Deposition","Melting or Vaporization","Condensation","Sublimation to Plasma"],"B",3,0,"417eb6b57467",1],["A student has four samples: oxygen, distilled water, brass, and sodium chloride. How many of these are pure substances?",["1","2","3","4"],"C",3,1,"457a1e2f2e5c",1],["A beaker contains a saturated solution of potassium nitrate at 40°C with some undissolved crystals at the bottom. Which statement must be true?",["Dissolving has completely stopped.","Crystallization occurs faster than dissolving.","No more solute can ever dissolve.","Dissolving and crystallization occur at equal rates"],"D",3,0,"2f63add9e421",1],["In an allotropic study, how does the hybridization of carbon in Diamond fundamentally dictate its physical hardness compared to Graphite?",["Diamond is heavier","Diamond's sp³ network creates a rigid 3D structure, whereas Graphite's sp² layers slide","Graphite has no carbon atoms","Diamond is a mixture, not an allotrope"],"B",3,0,"c40b300a677c",1],["When a saturated solution is prepared at 80oC and then rapidly cooled to 20oC without agitation, it may become 'supersaturated.' Why is this state thermodynamically unstable?",["The solute concentration exceeds the equilibrium solubility limit for 20oC","The solvent evaporates","The molecules stop moving","The pressure increases"],"A",3,0,"f178b15866dd",0],["In the context of the kinetic molecular theory, why do liquids exhibit fluidity?",["Their particles have zero kinetic energy","Their intermolecular forces are strong enough to hold volume, but weak enough to allow particle slippage","They are made of plasma","They have no mass"],"B",3,0,"827c29660e04",1],["Graphite conducts electricity, while diamond does not, even though both consist entirely of carbon atoms. This difference is primarily due to:",["Difference in purity","Difference in atomic mass","Difference in the number of carbon atoms","Difference in atomic arrangement and bonding"],"D",3,0,"480713cd962e",1],["A gas occupies 500 cm³ in a container. If transferred to a 1000 cm³ container at the same temperature, the gas will:",["Occupy 1000 cm³","Occupy 500 cm³ only","Remain at the bottom of the container","Become a liquid"],"A",3,0,"5f817d2fdd92",1],["A chemist claims that a sample is an element because it cannot be separated by chemical means. Why is this reasoning incomplete?",["Some compounds also cannot be separated chemically.","Elements have fixed compositions.","The sample might be a mixture.","The inability to separate chemically does not alone prove it contains only one type of atom."],"D",3,1,"6686e35dbee4",1],["If all intermolecular forces in a solid were suddenly reduced to nearly zero, the solid would most likely:",["Remain unchanged","Become more rigid","Behave like a gas","Become an element"],"C",3,0,"8025be33937e",1],["Which of the following correctly describes the relationship between particle size and the Tyndall effect?",["Particles must be smaller than the wavelength of light","Particles must be of a size that effectively scatters light (1-1000 nm)","Particles must be larger than 1000 nm","Particle size has no effect"],"B",3,0,"87f0a9905a14",1],["In a suspension, the term \"stationary\" refers to:",["The mixture is being heated","The state where the mixture is left undisturbed, allowing gravity to act on particles","The state where light is blocked","The state where the mixture is moving rapidly"],"B",3,0,"da446acbeaea",1],["When analyzing the internal structure of matter, what does the term 'intermolecular spacing' explain about compressibility?",["Large spacing allows particles to be pushed closer together","Small spacing prevents compression","Spacing has no relation to compressibility","Large spacing makes compression impossible"],"A",3,0,"cdb41950dec0",1],["When a solute is added to a solvent, why does the freezing point of the resulting solution often decrease?",["Because the solution gets hotter","Because the solvent becomes a gas","Because the solute is a metal","Because the solute disrupts the crystal lattice formation of the solvent"],"D",3,0,"88b5b8ce6ef6",1],["Why is the formation of a compound considered a chemical change, while the formation of a mixture is a physical change?",["Compounds have fixed mass ratios; mixtures have variable ratios","Mixtures are always solids","Compounds are always liquids","There is no difference"],"A",3,0,"2cf67ecf6dc4",1],["Two colorless liquids are placed in separate beakers. One is pure water, and the other is a salt solution. Which property would most reliably distinguish them?",["Color","Composition","State","Transparency"],"B",3,0,"73dbc475098c",1],["Which process involves the greatest increase in particle freedom?",["Steam → Water","Water → Ice","Water → Steam","Ice → Water"],"C",3,0,"ca40f6849085",1],["A mixture of iron filings and sulfur appears uniform after thorough mixing. Why is it still considered a mixture?",["It contains two elements not chemically combined.","It has a fixed composition.","New properties have developed.","It cannot be separated physically."],"A",3,0,"1c832c3baa03",1],["A gas occupies a container of 2 L. If transferred to a 5 L container at the same temperature, the gas will:",["Increase its mass.","Become a liquid.","Expand to fill the 5 L container.","Occupy exactly 2 L."],"C",3,0,"542b0eda4213",1],["If a solid carbon allotrope contains C₆₀ molecules arranged in a specific geometry, it is identified as:",["Diamond","Fullerene","Coal","Graphite"],"B",3,1,"12390239f056",1],["A student claims that because air is invisible, it is not matter. Which observation most directly disproves this claim?",["Air is transparent.","Air contains oxygen.","Air is colorless.","Air can be compressed."],"D",3,1,"20872f815397",1],["Why are Bose-Einstein Condensates (BEC) considered an \"exotic\" state of matter?",["They are found in volcanoes","They occur only at temperatures near absolute zero, where quantum effects become macroscopic","They are used to make steel","They are a form of smoke"],"B",3,0,"b6efe48f8ded",1],["Which statement would be FALSE for every saturated solution at a given temperature?",["It contains dissolved solute.","Additional solute can dissolve without changing conditions.","Dissolving and crystallization may occur simultaneously.","Its concentration has reached a maximum value under those conditions."],"B",3,0,"3e57d7961dbf",1],["Which of the following mixtures exhibits particles that can be separated by dialysis but not by filter paper?",["Suspension","Colloid","True Solution","Compound"],"B",3,0,"52d63e8641ca",1],["Why do amorphous solids lack a definite melting point compared to crystalline solids?",["Because they have stronger intermolecular forces","Because they are actually liquids","Because they have higher density","Because they lack a long-range ordered internal structure"],"D",3,0,"6005f2000227",1],["The density of a gas is inversely proportional to its volume at constant pressure. This physical behavior is rooted in:",["The compressibility of the gas due to vast intermolecular spaces","The chemical bonding between atoms","The high fluidity of the gas","The plasma state"],"A",3,0,"de580a030b6f",1],["Which of the following correctly describes the relationship between particle size and the Tyndall effect?",["Particles must be smaller than the wavelength of light","Particles must be of a size that effectively scatters light","Particles must be larger than 1000 nm","Particle size has no effect"],"B",3,0,"78313328aa2e",0],["Chalk powder stirred into water settles at the bottom after some time. This mixture is a:",["true solution","suspension","colloid","compound"],"B",1,1,"934630e027ce",0],["In which state are the particles most widely spaced and least ordered?",["Ice","Liquid water","Steam","Iron"],"C",1,0,"345d99898525",0],["A torch beam becomes visible when it passes through fog, but not through salt water. Fog is therefore a:",["true solution","colloid","compound","pure element"],"B",3,1,"78313328aa2e",0],["Unlike diamond, graphite is used in electrodes because it:",["is harder","conducts electricity","has no carbon","is transparent"],"B",3,0,"d1356997af2c",0],["A balloon becomes firm when air is blown into it. This shows that the air particles:",["are stationary","collide continuously with the walls and exert pressure","have no mass","turn into liquid"],"B",3,1,"09a7088b46db",0],["A pumped-up football is heavier than a flat one. This observation shows that air:",["has mass and is matter","is invisible","is a colour","is not matter"],"A",3,1,"20872f815397",0],["In a saturated solution at a fixed temperature, adding more solute:",["makes it dissolve completely","leaves the extra solute undissolved","turns the solution into a gas","removes the solvent"],"B",3,0,"3e57d7961dbf",0],["Liquids can flow and take the shape of their container because their particles:",["are held in fixed positions","can slide past each other while staying close","have no forces between them","do not move"],"B",3,0,"827c29660e04",0],["25 g of sugar is dissolved in 75 g of water. The concentration of the solution by mass is:",["75%","12.5%","33.3%","25%"],"D",3,1,"gen-chemistry-c2-mass-percent",0],["5 g of urea is dissolved in 95 g of water. The concentration of the solution by mass is:",["5%","2.5%","95%","5.3%"],"A",3,1,"gen-chemistry-c2-mass-percent",0],["25 g of urea is dissolved in 75 g of water. The concentration of the solution by mass is:",["33.3%","75%","12.5%","25%"],"D",3,1,"gen-chemistry-c2-mass-percent",0],["20 g of urea is dissolved in 30 g of water. The concentration of the solution by mass is:",["66.7%","60%","40%","20%"],"C",3,1,"gen-chemistry-c2-mass-percent",0],["5 g of copper sulphate is dissolved in 245 g of water. The concentration of the solution by mass is:",["2%","1%","5%","98%"],"A",3,1,"gen-chemistry-c2-mass-percent",0],["10 g of urea is dissolved in 90 g of water. The concentration of the solution by mass is:",["5%","10%","11.1%","90%"],"B",3,1,"gen-chemistry-c2-mass-percent",0],["Which property best explains why gases can be compressed much more easily than liquids?",["Higher density","Stronger intermolecular forces","Large empty spaces between particles","Fixed shape"],"C",3,0,"43f251541afa",1],["Which statement is true for all compounds?",["Their components can be separated by filtration.","They contain atoms of more than one element chemically combined.","Their composition is always variable.","They are heterogeneous."],"B",3,0,"d481e36043a5",1],["Why is \"air\" classified as a mixture rather than a compound?",["Because it is invisible","Because it is made of different gases that retain their individual properties","Because it has a fixed chemical formula","Because it only contains oxygen"],"B",3,0,"37486d8c84dd",1],["Which state of matter generally has neither a fixed shape nor a fixed volume?",["Gas","Solid","Liquid","Crystal"],"A",3,0,"c54120388e74",1],["Which property would be most useful in distinguishing a homogeneous mixture from a pure compound?",["Variable composition from sample to sample","Uniform appearance","Presence of particles","Colour"],"A",5,0,"20bdfe783690",1],["When a saturated solution is prepared at 80^oC and then rapidly cooled to 20^oC without agitation, it may become 'supersaturated.' Why is this state thermodynamically unstable?",["The solute concentration exceeds the equilibrium solubility limit for 20^oC","The solvent evaporates","The molecules stop moving","The pressure increases"],"A",5,0,"0cd60b4c262d",1],["A student prepares three solutions of the same solute at the same temperature:\nX: Unsaturated\nY: Saturated\nZ: Saturated with excess undissolved solute present\nWhich contains the greatest amount of dissolved solute per unit volume?",["X only","Y only","Z only","Y and Z"],"D",5,0,"88695a4b179b",1],["Ali melts a piece of wax in a test tube by heating it in a water bath. After removing the heat source, he observes that the liquid wax slowly turns back into a solid.\n\nWhat is the name of the process when liquid wax turns into a solid?",["Condensation","Evaporation","Freezing","Melting"],"C",5,1,"1314bd75018d",1],["Ali melts a piece of wax in a test tube by heating it in a water bath. After removing the heat source, he observes that the liquid wax slowly turns back into a solid.\n\nWhy is this change considered a physical change?",["A new substance is formed","The chemical composition changes","The change is reversible and no new substance is formed","Heat is released permanently"],"C",5,1,"e046449f0c72",1],["Ali melts a piece of wax in a test tube by heating it in a water bath. After removing the heat source, he observes that the liquid wax slowly turns back into a solid.\n\nDuring this change, what happens to the particles of wax?",["They break into new atoms","They become chemically different","They come closer together without changing identity","They disappear"],"C",5,1,"7b5b63e51546",1],["Ali melts a piece of wax in a test tube by heating it in a water bath. After removing the heat source, he observes that the liquid wax slowly turns back into a solid.\n\nWhich property remains unchanged during this process?",["State","Shape","Chemical composition","Volume"],"C",5,1,"985b3e8c2470",1],["Hina puts 100 g of water at 20 °C in a beaker. She adds 50 g of potassium chloride (KCl) and stirs well. Some of the KCl does not dissolve. It stays at the bottom of the beaker. The table shows how much of four salts can dissolve in 100 g of water. At 20 °C: NaCl 36.5 g, KCl 34.7 g, NH₄Cl 37.5 g, Ca(OH)₂ 0.173 g. At 100 °C: NaCl 39.2 g, KCl 56 g, NH₄Cl 77 g, Ca(OH)₂ 0.066 g.\n\nAt 20 °C, the solution above the solid KCl is:",["Unsaturated","Saturated","Supersaturated","Not a solution at all"],"B",5,1,"ef18c725c457",1],["Hina puts 100 g of water at 20 °C in a beaker. She adds 50 g of potassium chloride (KCl) and stirs well. Some of the KCl does not dissolve. It stays at the bottom of the beaker. The table shows how much of four salts can dissolve in 100 g of water. At 20 °C: NaCl 36.5 g, KCl 34.7 g, NH₄Cl 37.5 g, Ca(OH)₂ 0.173 g. At 100 °C: NaCl 39.2 g, KCl 56 g, NH₄Cl 77 g, Ca(OH)₂ 0.066 g.\n\nHina heats the beaker to 100 °C and stirs. What happens to the KCl at the bottom?",["More KCl settles at the bottom","The amount at the bottom stays the same","All of it dissolves","It changes into something new"],"C",5,1,"01abb4488f40",1],["Hina puts 100 g of water at 20 °C in a beaker. She adds 50 g of potassium chloride (KCl) and stirs well. Some of the KCl does not dissolve. It stays at the bottom of the beaker. The table shows how much of four salts can dissolve in 100 g of water. At 20 °C: NaCl 36.5 g, KCl 34.7 g, NH₄Cl 37.5 g, Ca(OH)₂ 0.173 g. At 100 °C: NaCl 39.2 g, KCl 56 g, NH₄Cl 77 g, Ca(OH)₂ 0.066 g.\n\nHina keeps the water at 100 °C. How much more KCl can she still dissolve in it?",["6 g","15.3 g","21.3 g","56 g"],"A",5,1,"7a6395809079",1],["Hina puts 100 g of water at 20 °C in a beaker. She adds 50 g of potassium chloride (KCl) and stirs well. Some of the KCl does not dissolve. It stays at the bottom of the beaker. The table shows how much of four salts can dissolve in 100 g of water. At 20 °C: NaCl 36.5 g, KCl 34.7 g, NH₄Cl 37.5 g, Ca(OH)₂ 0.173 g. At 100 °C: NaCl 39.2 g, KCl 56 g, NH₄Cl 77 g, Ca(OH)₂ 0.066 g.\n\nHina's friend Asma makes a saturated solution of calcium hydroxide, Ca(OH)₂, at 20 °C. She heats it to 100 °C. What will she see?",["More calcium hydroxide dissolves","Nothing changes","The solution becomes unsaturated","Some solid calcium hydroxide comes out of the solution"],"D",5,1,"f47ecff53e33",1],["A student is given four samples: P: distilled water, Q: air, R: salt dissolved completely in water, S: muddy water. The student observes that P has a fixed composition, Q contains several gases, R is uniform throughout, and solid particles in S settle when it is left undisturbed.\n\nWhich sample represents a pure compound?",["P","Q","R","S"],"A",5,1,"0d212ab70179",1],["A student is given four samples: P: distilled water, Q: air, R: salt dissolved completely in water, S: muddy water. The student observes that P has a fixed composition, Q contains several gases, R is uniform throughout, and solid particles in S settle when it is left undisturbed.\n\nWhich sample can be separated by physical methods because its components are not chemically bonded?",["P only","Q only","P and Q","Q, R and S"],"D",5,1,"f531ce1522cd",1],["A student is given four samples: P: distilled water, Q: air, R: salt dissolved completely in water, S: muddy water. The student observes that P has a fixed composition, Q contains several gases, R is uniform throughout, and solid particles in S settle when it is left undisturbed.\n\nA beam of light is passed through R and S. Which observation is most likely?",["R scatters light strongly, while S does not","S scatters light, while R does not show the Tyndall effect","Both scatter light equally","Neither can transmit light"],"B",5,1,"b549f93ab384",1],["A student is given four samples: P: distilled water, Q: air, R: salt dissolved completely in water, S: muddy water. The student observes that P has a fixed composition, Q contains several gases, R is uniform throughout, and solid particles in S settle when it is left undisturbed.\n\nIf some water is evaporated from R without allowing the salt to crystallize, the concentration of the solution will:",["Decrease","Remain unchanged","Increase","Become zero"],"C",5,1,"4af2f47602d3",1],["A student is given four samples: P: distilled water, Q: air, R: salt dissolved completely in water, S: muddy water. The student observes that P has a fixed composition, Q contains several gases, R is uniform throughout, and solid particles in S settle when it is left undisturbed.\n\nWhich statement correctly distinguishes P from Q?",["P contains different substances in variable proportions","Q has a fixed chemical formula","P has chemically combined elements in a fixed ratio, whereas Q is a mixture","Both are compounds because both are homogeneous"],"C",5,1,"5f5cb77206ef",1],["A student prepares a solution by adding 40 g of a solid solute to 100 g of water at 50°C. At this temperature, the maximum amount that can dissolve is 30 g. The student then studies two forms of carbon, X and Y. X is extremely hard and does not conduct electricity, while Y is soft and conducts electricity.\n\nWhat type of solution is initially obtained after adding 40 g of solute?",["Unsaturated solution","Saturated solution with 10 g undissolved solute","Supersaturated solution","Dilute solution containing all 40 g dissolved"],"B",5,1,"c7f645fa6800",1],["A student prepares a solution by adding 40 g of a solid solute to 100 g of water at 50°C. At this temperature, the maximum amount that can dissolve is 30 g. The student then studies two forms of carbon, X and Y. X is extremely hard and does not conduct electricity, while Y is soft and conducts electricity.\n\nIf the temperature is increased and the solubility of the solute increases, what is most likely to happen to the undissolved solute?",["More solute may dissolve","All water immediately evaporates","The solute changes into an element","The solution becomes a suspension"],"A",5,1,"69c30cd69123",1],["A student prepares a solution by adding 40 g of a solid solute to 100 g of water at 50°C. At this temperature, the maximum amount that can dissolve is 30 g. The student then studies two forms of carbon, X and Y. X is extremely hard and does not conduct electricity, while Y is soft and conducts electricity.\n\nX and Y are best classified as:",["Isotopes","Compounds","Allotropes of carbon","Mixtures of carbon"],"C",5,1,"e653d251e2d7",1],["A student prepares a solution by adding 40 g of a solid solute to 100 g of water at 50°C. At this temperature, the maximum amount that can dissolve is 30 g. The student then studies two forms of carbon, X and Y. X is extremely hard and does not conduct electricity, while Y is soft and conducts electricity.\n\nThe different properties of X and Y are mainly due to differences in their:",["Atomic numbers","Number of protons","Arrangement and bonding of carbon atoms","Chemical symbols"],"C",5,1,"d7199b2e97f2",1],["A student prepares a solution by adding 40 g of a solid solute to 100 g of water at 50°C. At this temperature, the maximum amount that can dissolve is 30 g. The student then studies two forms of carbon, X and Y. X is extremely hard and does not conduct electricity, while Y is soft and conducts electricity.\n\nWhich combination correctly identifies X and Y?",["X = graphite, Y = diamond","X = diamond, Y = graphite","X = buckminsterfullerene, Y = diamond","X = graphite, Y = buckminsterfullerene"],"B",5,1,"2b403c8aa0df",1]]$j$::jsonb, true);
